                    colorscale=[[0, "#F4FAF7"], [0.35, "#C5E5DA"], [0.70, "#73B5A1"], [1, "#2F7569"]],
                    hovertemplate="Observed %{y}<br>Predicted %{x}<br>%{z:,} locations<extra></extra>",
